    if (Object.values(marks).some(v => v === null)) return { err: 'Une note dépasse le maximum (' + f.max + ') ou est négative' }; const rec = { classId: cl.id, subject: f.subject, term: SC.TERMS.includes(f.term) ? f.term : 'T1', kind: SC.KINDS.includes(f.kind) ? f.kind : SC.KINDS[1], title: f.title || '', max: f.max, date: f.date || App.today(), marks };
